F=/scratch/jjyeung/orch_n30/fb_pack; R=/scratch/jjyeung/orch_n30
mkdir -p $F/relrev2; cp $R/sb_cursor_probe/AGENTS.md $F/relrev2/AGENTS.md; echo  | base64 -d > $F/relrev2/PROMPT.md; sha256sum $F/relrev2/PROMPT.md | cut -c1-12
ls $F/relrev/REVIEW_VERDICT.md
cd $F/relrev2 && tmux new-session -d -s fbp_relrev2 "OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 nice -n 10 timeout 5400 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes. Write only in this folder.' > $F/relrev2/cursor.log 2>&1" </dev/null >/dev/null 2>&1
sleep 3; tmux ls | grep fbp | cut -c1-24; date -u +%TZ; df -h /scratch | tail -1
